parameters.jsCode:
const err = $input.item.json;
const execution = err.execution || {};
const workflow = err.workflow || {};
const trigger = err.trigger || {};
return {
  json: {
    incident_id: 'inc_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7),
    workflow_name: workflow.name || 'unknown_workflow',
    workflow_id: workflow.id || 'unknown',
    execution_id: execution.id || 'unknown',
    execution_url: execution.url || '',
    node_name: err.node ? err.node.name : 'unknown_node',
    error_message: (err.error && (err.error.message || err.error.description)) || String(err.error || 'Unknown error'),
    error_stack: (err.error && err.error.stack) || '',
    trigger_payload: trigger,
    occurred_at: new Date().toISOString(),
    severity: 'high'
  }
};

parameters.text:
=*Agency email automation incident*

*Workflow:* {{ $json.workflow_name }}
*Node:* {{ $json.node_name }}
*Execution:* {{ $json.execution_url }}
*Error:* {{ $json.error_message }}

No email should be treated as sent until this incident is reviewed.
